    -- ===== Parent to CoreGui =====
    root.Parent = game:GetService("CoreGui")

    -- ===== Make window draggable =====
    local dragging, dragStart, startPos
    o903958.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            dragStart = input.Position
            startPos = o903958.Position
        end
    end)
    o903958.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
    end)
    UserInput.InputChanged:Connect(function(input)
        if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
            local delta = input.Position - dragStart
            o903958.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)

    -- ===== Close button =====
    o727198.MouseButton1Click:Connect(function() root:Destroy() end)

    -- ===== Tab switching =====
    local tabButtons = {o489062, o489538, o608358, o289411, o590269}
    local tabPages = {o821220, o100739, o229223, o541086}
    local function selectTab(idx)
        for i, page in ipairs(tabPages) do
            page.Visible = (i == idx)
        end
    end
    for i, btn in ipairs(tabButtons) do
        if i <= #tabPages then
            btn.MouseButton1Click:Connect(function() selectTab(i) end)
        end
    end
    selectTab(1)

    -- ===== Helper: wrap a toggle button with callback =====
    local function makeToggle(btn, knob, defaultState, callback)
        local state = defaultState or false
        local function update()
            if state then
                tween(knob, 0.15, { Position = UDim2.new(1, -23, 0.5, 0) })
                btn.BackgroundColor3 = Color3.fromRGB(108, 182, 255)
            else
                tween(knob, 0.15, { Position = UDim2.new(0, 3, 0.5, 0) })
                btn.BackgroundColor3 = Color3.fromRGB(48, 48, 48)
            end
        end
        update()
        btn.MouseButton1Click:Connect(function()
            state = not state
            update()
            if callback then callback(state) end
        end)
        return {
            Get = function() return state end,
            Set = function(s) state = s; update(); if callback then callback(state) end end,
            OnToggle = function(cb) callback = cb end,
        }
    end

    -- ===== Helper: wrap a button with callback =====
    local function makeButton(btn, callback)
        local cb = callback
        btn.MouseButton1Click:Connect(function()
            if cb then cb() end
        end)
        return {
            OnClick = function(newCb) cb = newCb end,
        }
    end

    -- ===== Console =====
    local Console = {}
    local consoleLabel = o614163
    local consoleLogs = {}
    local LEVEL_COLORS = {
        info = "#6cb6ff", warn = "#ffd60a", error = "#ff5555",
        success = "#7CFC00", debug = "#8c8c8c",
    }
    function Console.Log(msg, level)
        level = level or "info"
        local color = LEVEL_COLORS[level] or "#ffffff"
        local ts = os.date("%H:%M:%S")
        local line = string.format('<font color="#8c8c8c">%s</font>  <font color="%s">%s</font>\n', ts, color, tostring(msg))
        table.insert(consoleLogs, line)
        consoleLabel.Text = table.concat(consoleLogs, "")
    end
    function Console.Info(msg) Console.Log(msg, "info") end
    function Console.Warn(msg) Console.Log(msg, "warn") end
    function Console.Error(msg) Console.Log(msg, "error") end
    function Console.Success(msg) Console.Log(msg, "success") end
    function Console.Clear() consoleLogs = {}; consoleLabel.Text = "" end

